#nullable enable
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public sealed class OutputKey
{
    public Definition Definition { get; }
    public Spec? Spec { get; }
    public object Value { get; }
    public string Notation { get; }

    public OutputKey(Definition definition, Spec? spec, object value)
    {
        Definition = definition;
        Spec = spec;
        Value = value;
        Notation = Emitter.ValueNotation(spec?.Kind ?? "string", spec?.Item ?? "string", value);
    }
}

public static class Emitter
{
    public const string Mask = "********";

    public static string StringNotation(string text)
    {
        var result = new StringBuilder("\"");
        foreach (char c in text)
            result.Append(c switch
            {
                '\\' => "\\\\", '"' => "\\\"", '\n' => "\\n", '\t' => "\\t", _ => c.ToString()
            });
        return result.Append('"').ToString();
    }

    public static string ValueNotation(string kind, string item, object value) => kind switch
    {
        "string" => StringNotation((string)value),
        "bool" => (bool)value ? "true" : "false",
        "list" => "[" + string.Join(", ", ((List<object>)value).Select(v => ValueNotation(item, "string", v))) + "]",
        "int" or "size" or "duration" => ((long)value).ToString(CultureInfo.InvariantCulture),
        _ => (string)value
    };

    public static string Shown(OutputKey output) => output.Spec?.Secret == true ? Mask : output.Notation;

    private static IEnumerable<string> Normalized(Profile profile)
    {
        yield return "profile " + profile.Name;
        string? previous = null;
        foreach (string key in KeyNames.Sorted(profile.Outputs.Keys))
        {
            string section = KeyNames.Section(key);
            if (section != previous)
            {
                yield return "[" + section + "]";
                previous = section;
            }
            yield return KeyNames.Name(key) + " = " + Shown(profile.Outputs[key]);
        }
    }

    private static IEnumerable<string> Diagnostics(Profile profile)
    {
        yield return $"profile {profile.Name} errors {profile.Errors} warnings {profile.Warnings}";
        foreach (Diagnostic diagnostic in profile.Diagnostics)
            yield return $"{diagnostic.Origin} {diagnostic.Code} {diagnostic.Message}";
    }

    private static IEnumerable<string> Diff(ProfileDiff diff)
    {
        yield return $"diff {diff.First} -> {diff.Second}: {diff.Added} added, {diff.Removed} removed, {diff.Changed} changed";
        foreach (DiffEntry entry in diff.Entries)
            yield return entry.Sign switch
            {
                '+' => $"+ {entry.Key} = {Shown(entry.After!)}",
                '-' => $"- {entry.Key} = {Shown(entry.Before!)}",
                _ => $"~ {entry.Key}: {Shown(entry.Before!)} -> {Shown(entry.After!)}"
            };
    }

    private static IEnumerable<string> Report(Profile profile)
    {
        yield return "profile " + profile.Name;
        yield return "includes";
        foreach (var line in profile.Tree)
            yield return new string(' ', 2 + 2 * line.Depth) + line.Text;
        yield return "overridden";
        foreach (var entry in profile.Overridden)
            yield return "  " + entry.Key + ": " + string.Join(" -> ", entry.History);
        if (profile.Overridden.Count == 0)
            yield return "  (none)";
        yield return $"keys {profile.Outputs.Count} documents {profile.DocumentKeys} manifest {profile.ManifestKeys} defaults {profile.DefaultKeys}";
        yield return $"dropped {profile.Dropped}";
        yield return $"errors {profile.Errors} warnings {profile.Warnings}";
    }

    private static void Write(string path, IEnumerable<IEnumerable<string>> blocks) =>
        File.WriteAllText(path, string.Join("\n\n", blocks.Select(block => string.Join('\n', block))) + "\n", new UTF8Encoding(false));

    public static void WriteOutputs(string directory, IEnumerable<Profile> profiles, IEnumerable<ProfileDiff> diffs)
    {
        Directory.CreateDirectory(directory);
        Write(Path.Combine(directory, "normalized.txt"), profiles.Select(Normalized));
        Write(Path.Combine(directory, "diagnostics.txt"), profiles.Select(Diagnostics));
        Write(Path.Combine(directory, "diff.txt"), diffs.Select(Diff));
        Write(Path.Combine(directory, "report.txt"), profiles.Select(Report));
    }
}

#nullable enable
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

public sealed record Statement(string Kind, int Line, string Target, string Value = "");

public sealed class Document
{
    public List<Statement> Statements { get; } = new();
    public List<Diagnostic> Diagnostics { get; } = new();
}

public sealed class IniParser
{
    private readonly string documentName;
    private readonly Document document = new();
    private readonly Dictionary<string, int> assigned = new(StringComparer.Ordinal);
    private string? section;
    private string? baseSection;

    private IniParser(string name) => documentName = name;

    public static bool IsName(string text) => Regex.IsMatch(text, @"\A[a-z][a-z0-9_]*\z");
    public static bool IsSection(string text) =>
        Regex.IsMatch(text, @"\A[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)*\z");

    public static Document Parse(string name, IReadOnlyList<string> lines)
    {
        var parser = new IniParser(name);
        foreach (LogicalLine line in Lexer.Read(lines))
            parser.Interpret(line);
        return parser.document;
    }

    private void Report(int line, string code, string message) =>
        document.Diagnostics.Add(new Diagnostic(new Origin(documentName, line), code, message));

    private void Add(string kind, int line, string target, string value = "") =>
        document.Statements.Add(new Statement(kind, line, target, value));

    private static List<string> Trimmed(IEnumerable<string> segments)
    {
        List<string> result = segments.ToList();
        result[0] = result[0].TrimStart(' ');
        result[^1] = result[^1].TrimEnd(' ');
        return result;
    }

    private void Interpret(LogicalLine line)
    {
        if (line.Error is { } error)
        {
            Report(line.Number, error.Code, error.Message);
            return;
        }
        List<string> segments = Trimmed(line.Segments);
        string first = segments[0];
        if (segments.Count == 1 && first == "")
            return;
        if (first.StartsWith('['))
            Header(line.Number, segments);
        else if (first.StartsWith('@'))
            Directive(line.Number, segments);
        else
            Assignment(line.Number, segments);
    }

    private void BadHeader(int line, string message)
    {
        Report(line, "E_SECTION", message);
        section = null;
    }

    private void Header(int line, List<string> segments)
    {
        string text = segments[0];
        if (segments.Count != 1 || !text.EndsWith(']'))
        {
            BadHeader(line, "invalid section header");
            return;
        }
        string inside = text[1..^1];
        int colon = inside.IndexOf(':');
        string name = (colon < 0 ? inside : inside[..colon]).Trim(' ');
        string? parent = colon < 0 ? null : inside[(colon + 1)..].Trim(' ');
        bool relative = name.StartsWith('.') && IsSection(name[1..]);
        if ((parent != null && !IsSection(parent)) || (!relative && !IsSection(name)))
            BadHeader(line, "invalid section header");
        else if (relative && baseSection == null)
            BadHeader(line, "relative section without base");
        else
        {
            if (relative)
                section = baseSection + name;
            else
                section = baseSection = name;
            if (parent != null)
                Add("inherit", line, section!, parent);
        }
    }

    private void Directive(int line, List<string> segments)
    {
        string[] words = segments[0].Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (segments.Count != 1 || words.Length != 2 ||
            (words[0] != "@include" && words[0] != "@unset") || !IsName(words[1]))
            Report(line, "E_SYNTAX", "invalid directive");
        else if (words[0] == "@include")
            Add("include", line, words[1]);
        else if (section == null)
            Report(line, "E_NO_SECTION", "no current section");
        else
            Add("unset", line, section + "." + words[1]);
    }

    private void Assignment(int line, List<string> segments)
    {
        bool hasEquals = segments.Where((_, index) => index % 2 == 0).Any(s => s.Contains('='));
        int equals = segments[0].IndexOf('=');
        if (!hasEquals)
        {
            Report(line, "E_SYNTAX", "invalid line");
            return;
        }
        if (equals < 0)
        {
            Report(line, "E_SYNTAX", "invalid key");
            return;
        }
        string key = segments[0][..equals].Trim(' ');
        bool append = key.EndsWith('+');
        if (append)
            key = key[..^1].TrimEnd(' ');
        if (!IsName(key))
        {
            Report(line, "E_SYNTAX", "invalid key");
            return;
        }
        segments[0] = segments[0][(equals + 1)..];
        List<string> parts = Trimmed(segments);
        string? value = parts.Count == 1 ? parts[0] :
            parts.Count == 3 && parts[0] == "" && parts[2] == "" ? parts[1] : null;
        if (value == null)
            Report(line, "E_SYNTAX", "invalid value");
        else if (section == null)
            Report(line, "E_NO_SECTION", "no current section");
        else
        {
            string fullKey = section + "." + key;
            if (!append)
            {
                if (assigned.TryGetValue(fullKey, out int previous))
                    Report(line, "W_DUPLICATE", $"{fullKey} already set at line {previous}");
                assigned[fullKey] = line;
            }
            Add(append ? "append" : "assign", line, fullKey, value);
        }
    }
}

